  { id: "maif",             name: "MAIF",             color: "#ED2131", initials: "MI", asset: "maif-mask.png" }, // masque fabriqué, encre 0.37
  { id: "swisslife",        name: "Swiss Life",       color: "#E50028", initials: "SL", asset: "swisslife.svg" }, // encre 0.18
